<?php $this->assign('title', 'Pacientes'); ?><div class="d-flex justify-content-between mb-4"><div><h1 class="h3">Pacientes</h1><p class="text-body-secondary">Cadastro e histórico clínico com acesso controlado.</p></div><?= $this->Html->link('Novo paciente', ['action' => 'add'], ['class' => 'btn btn-primary']) ?></div><form class="card card-body border-0 shadow-sm mb-3"><div class="input-group"><input name="busca" value="<?= h($busca) ?>" class="form-control" placeholder="Nome ou nome social"><button class="btn btn-outline-primary">Pesquisar</button></div></form><div class="card border-0 shadow-sm"><table class="table table-hover mb-0"><thead><tr><th>Nome</th><th>Nascimento</th><th>Telefone</th><th>Status</th><th></th></tr></thead><tbody><?php foreach ($pacientes as $paciente): ?><tr><td><?= $this->Html->link($paciente->nome_social ?: $paciente->nome_completo, ['action' => 'view', $paciente->id]) ?></td><td><?= h($paciente->data_nascimento->format('d/m/Y')) ?></td><td><?= h($paciente->telefone ?: '-') ?></td><td><?= $paciente->ativo ? 'Ativo' : 'Inativo' ?></td><td><?= $this->Html->link('Editar', ['action' => 'edit', $paciente->id], ['class' => 'btn btn-sm btn-outline-primary']) ?></td></tr><?php endforeach; ?></tbody></table></div>
